/*
 * A126842  Ramanujan numbers (A000594) read mod 13.
 * https://oeis.org/A126842
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = Ramanujan tau function τ(n) modulo 13. The sequence a(1)
 *            = 1, a(2) = 2, a(3) = 5, a(4) = 10, a(5) = 7, … is generated by
 *            taking the coefficients of the modular discriminant Δ(q) =
 *            q∏(1−q^m)^24 (Ramanujan's tau function) and reducing them modulo
 *            13. The implementation computes the needed co...
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>

static const idx_t MAX_N = 10000;          // maximum index we precompute

/* Precomputed coefficients of (1 - q^m)^24 modulo 13.
   coeff[j] = C(24, j) * (-1)^j  (mod 13).          */
static uint8_t coeff[25];                    // 0..24

/* Cached values of a(n) for 1 ≤ n ≤ MAX_N. */
static seq_t *cache = NULL;
static int cache_size = 0;

/* Compute the modular coefficients of (1 - q^m)^24. */
static void init_coeff(void)
{
    /* integer binomial coefficients C(24, j) */
    int binom[25];
    binom[0] = 1;
    for (int j = 1; j <= 24; ++j)
        binom[j] = binom[j-1] * (24 - j + 1) / j;   /* exact division */

    coeff[0] = 1 % 13;
    for (int j = 1; j <= 24; ++j) {
        int c = binom[j];
        if (j & 1)
            c = -c;                 /* (-1)^j */
        c %= 13;
        if (c < 0)
            c += 13;
        coeff[j] = (uint8_t)c;
    }
}

/* Precompute all a(n) up to MAX_N modulo 13. */
static void precompute(void)
{
    if (cache != NULL)
        return;                    /* already done */

    init_coeff();

    /* Buffers for the product coefficients. */
    int *prod  = (int *)malloc((MAX_N + 1) * sizeof(int));
    int *prod2 = (int *)malloc((MAX_N + 1) * sizeof(int));
    if (!prod || !prod2) {
        /* allocation failure – abort rather than continue */
        exit(1);
    }

    /* product initially = 1 */
    for (int i = 0; i <= MAX_N; ++i)
        prod[i] = 0;
    prod[0] = 1 % 13;

    for (int m = 1; m <= MAX_N; ++m) {
        /* clear new buffer */
        for (int i = 0; i <= MAX_N; ++i)
            prod2[i] = 0;

        for (int k = 0; k <= MAX_N; ++k) {
            if (prod[k] == 0)
                continue;

            int ak = prod[k];
            int maxj = (MAX_N - k) / m;
            if (maxj > 24)
                maxj = 24;

            for (int j = 0; j <= maxj; ++j) {
                int idx = k + m * j;
                int add = (ak * coeff[j]) % 13;
                prod2[idx] = (prod2[idx] + add) % 13;
            }
        }
        /* swap buffers */
        int *tmp = prod;
        prod = prod2;
        prod2 = tmp;
    }

    /* store the cached values: a(n) = prod[n-1]  (n>=1)  */
    cache = (seq_t *)malloc((MAX_N + 1) * sizeof(seq_t));
    if (!cache) {
        exit(1);
    }
    cache[0] = 0;                     /* unused, offset 1 */
    for (int n = 1; n <= MAX_N; ++n) {
        cache[n] = (seq_t)(prod[n-1] % 13);
    }

    cache_size = MAX_N + 1;

    free(prod);
    free(prod2);
}

/* Sequence generator */
seq_t a(idx_t n)
{
    if (n == (idx_t)0)          /* offset 1 – undefined behaviour below */
        return (seq_t)0;

    precompute();

    if (n < cache_size)         /* always true for n <= MAX_N */
        return cache[(size_t)n];

    /* If a larger n is requested, compute only up to that n on demand. */
    /* (Not required by the problem statement but keeps the function safe.) */
    const idx_t new_size = (idx_t)(n + 1);
    cache = (seq_t *)realloc(cache, sizeof(seq_t) * new_size);
    if (!cache) {
        exit(1);
    }

    /* Grow the product computation to the new size.  Use the same
       algorithm as above but starting from the last computed degree. */
    int *prod = (int *)calloc(new_size, sizeof(int));
    int *prod2 = (int *)calloc(new_size, sizeof(int));
    if (!prod || !prod2) {
        exit(1);
    }

    prod[0] = 1 % 13;            /* initial product */

    /* Recompute from scratch up to new_size-1 */
    for (int m = 1; m <= (int)n; ++m) {
        for (int i = 0; i <= (int)n; ++i)
            prod2[i] = 0;

        for (int k = 0; k <= (int)n; ++k) {
            if (prod[k] == 0)
                continue;
            int ak = prod[k];
            int maxj = ((int)n - k) / m;
            if (maxj > 24)
                maxj = 24;
            for (int j = 0; j <= maxj; ++j) {
                int idx = k + m * j;
                int add = (ak * coeff[j]) % 13;
                prod2[idx] = (prod2[idx] + add) % 13;
            }
        }
        int *tmp = prod;
        prod = prod2;
        prod2 = tmp;
    }

    for (size_t i = 1; i <= n; ++i)
        cache[i] = (seq_t)(prod[i-1] % 13);

    cache_size = (int)new_size;

    free(prod);
    free(prod2);

    return cache[(size_t)n];
}
